@@ -0,0 +1,76 @@
+/**
+ * Custom CSS for MCPProxy Documentation
+ * Colors match mcpproxy.app marketing site
+ */
+
+/* You can override the default Infima variables here. */
+:root {
+  --ifm-color-primary: #3b82f6;
+  --ifm-color-primary-dark: #2563eb;
+  --ifm-color-primary-darker: #1d4ed8;
+  --ifm-color-primary-darkest: #1e40af;
+  --ifm-color-primary-light: #60a5fa;
+  --ifm-color-primary-lighter: #93c5fd;
+  --ifm-color-primary-lightest: #bfdbfe;
+  --ifm-font-family-base: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
+  --ifm-code-font-size: 95%;
+  --docusaurus-highlighted-code-line-bg: rgba(0, 0, 0, 0.1);
+}
+
+/* For readability concerns, you should choose a lighter palette in dark mode. */
+[data-theme='dark'] {
+  --ifm-color-primary: #60a5fa;
+  --ifm-color-primary-dark: #3b82f6;
+  --ifm-color-primary-darker: #2563eb;
+  --ifm-color-primary-darkest: #1d4ed8;
+  --ifm-color-primary-light: #93c5fd;
+  --ifm-color-primary-lighter: #bfdbfe;
+  --ifm-color-primary-lightest: #dbeafe;
+  --ifm-background-color: #0f172a;
+  --docusaurus-highlighted-code-line-bg: rgba(0, 0, 0, 0.3);
+}
+
+/* Version badge styling */
+.badge {
+  display: inline-block;
+  padding: 0.25rem 0.5rem;
+  font-size: 0.75rem;
+  font-weight: 600;
+  line-height: 1;
+  border-radius: 0.375rem;
+  margin-left: 0.5rem;
+}
+
+.badge--primary {
+  background-color: var(--ifm-color-primary);
+  color: white;
+}
+
+[data-theme='dark'] .badge--primary {
+  background-color: var(--ifm-color-primary-dark);
+}
+
+/* Make code blocks more readable */
+.prism-code {
+  font-size: 14px;
+}
+
+/* Improve table styling */
+table {
+  display: table;
+  width: 100%;
+}
+
+/* Better sidebar navigation */
+.menu__link {
+  font-size: 0.9rem;
+}
+
+/* Footer styling to match marketing site */
+.footer {
+  background-color: #0f172a;
+}
+
+.footer--dark {
+  --ifm-footer-background-color: #0f172a;
+}

@@ -0,0 +1,6 @@
+import React from 'react';
